/* Atelier — art therapy activities, part 3: play and joy, nature and seasons, more together and mindful making */
'use strict';

THERAPY.push(
  /* ---------- play and joy ---------- */
  { id: 'squiggle-game', th: 'joy', n: 'The squiggle game', sum: 'Taking turns to turn each other’s squiggles into pictures.',
    mins: 20, who: 'Ages 5 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 1,
    media: ['draw'],
    depth: 1,
    mat: ['Small sheets of paper, A5 or smaller', 'Two felt-tips or textas in different colours', 'Crayons or coloured pencils for finishing'],
    purpose: 'A turn-taking drawing game best known through the paediatrician Donald Winnicott, played here simply for fun. A squiggle is a tiny, no-pressure starting point, and the back-and-forth builds easy conversation, imagination and plenty of laughter.',
    steps: ['Sit with a partner, each with a small sheet of paper and a pen in a different colour.', 'Draw one quick squiggle: a single wiggly line, loop or zigzag, made in a few seconds.', 'Swap sheets and turn your partner’s squiggle into something: a creature, an object, a face or a scene.', 'Keep using your own colour, so you can both see where the squiggle ends and the picture begins.', 'Say what it became, then play again with fresh sheets, as many rounds as you like.', 'Lay all the pictures out in a row and see if they can be joined into one silly story.', 'Add colour to a favourite if you want to take it further.'],
    prompts: ['Keep the squiggle quick: no planning allowed.', 'Try it sideways or upside down before you decide.', 'There are no wrong answers, only surprising ones.'],
    adapt: ['One-to-one: the teacher plays as the partner, which makes a relaxed start to a first lesson.', 'Young children: offer chunky crayons and welcome any answer, even “a squiggle wearing a hat”.', 'Anyone who doesn’t want to draw can say what they see while their partner draws it.', 'Limited grip: use thick markers on larger paper taped to the table.'],
    reflect: ['Which squiggle was hardest to turn into something?', 'What did your partner see that you didn’t expect?', 'How did it feel to start from someone else’s line?'] },
  { id: 'folded-creatures', th: 'joy', n: 'Folded mix-up creatures', sum: 'Heads, bodies and legs drawn in secret, then unfolded.',
    mins: 25, who: 'Ages 5 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 1,
    media: ['draw'],
    depth: 1,
    mat: ['A4 paper, one sheet per person', 'Pencils, felt-tips or textas', 'Coloured pencils for finishing (optional)'],
    purpose: 'Surrealist artists in the 1920s played a version of this folding game called exquisite corpse, and many families know it as consequences. Each part stays hidden until the end, so nobody can control the result, perfectionism has nowhere to go, and the reveal almost always brings a laugh.',
    steps: ['Fold each sheet into four equal strips across the page, then open it out again.', 'In the top strip, draw a head: a creature, a person, a robot or anything at all. Keep it secret.', 'Draw the neck lines just over the fold into the next strip, then fold the head back so it’s hidden.', 'Pass the sheet on. The next person draws a body that joins the neck lines, then folds it back the same way.', 'Pass again for legs, then once more for feet, shoes, wheels or anything else to stand on.', 'Unfold the creatures one at a time for the big reveal.', 'Give each creature a name, then add colour or a home for it if there’s time.'],
    prompts: ['No peeking: the surprise is the best bit.', 'Leave two little lines poking over the fold so the next person knows where to join.', 'What would this creature eat for breakfast?'],
    adapt: ['One-to-one: use two sheets at once and swap with the teacher after each section.', 'Young children: three sections (head, body and legs), with a dot on each fold to show where to join.', 'Flip book version: draw creatures on cards in three matching sections, staple the cards along the left edge, then cut each card into three flaps to mix and match.', 'Older students can play the writing version too, folding and passing a silly story line by line.'],
    reflect: ['Which creature made you laugh the most?', 'How did it feel not knowing what the others had drawn?', 'Which name suits its creature best?'],
    care: 'Keep the laughter kind: everyone is laughing at the surprise, not at anyone’s drawing.' },
  { id: 'other-hand', th: 'joy', n: 'Other-hand drawing', sum: 'Drawing with the hand you don’t usually use.',
    mins: 20, who: 'Ages 6 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 1,
    media: ['draw'],
    depth: 1,
    mat: ['Paper, taped to the table so it doesn’t slide', 'Thick felt-tips, crayons or oil pastels', 'An object to draw, such as a mug, a shoe or a toy'],
    purpose: 'Drawing with the non-dominant hand makes everyone a beginner again, so wobbly lines are expected and nobody can aim for perfect. Many people find the results charming and the slowness surprisingly relaxing.',
    steps: ['Tape the paper down and hold the crayon in the hand you don’t usually draw with.', 'Warm up with big circles, zigzags and your name in giant letters.', 'Draw the object slowly, looking at it more than at the page.', 'Swap to your usual hand and draw the same object again beside it.', 'Swap back and draw something from memory with your other hand, such as a pet, a house or a favourite food.', 'Lay the drawings side by side and look for something you like in each one.'],
    prompts: ['Wobbly is the whole point.', 'Notice how slowly your hand wants to move.', 'Which drawing has the most character?'],
    adapt: ['If someone has limited use of one hand, skip the swap and loosen up another way, such as drawing with a crayon taped to a long stick.', 'Young children: draw a face or a house with each hand and compare.', 'Older adults: larger paper and chunky pastels are kinder on the joints.'],
    reflect: ['What felt different about drawing with your other hand?', 'Which drawing do you like best?', 'Did you notice anything about how you usually draw?'],
    care: 'This can feel frustrating at first. Keep it light and short, and let anyone switch back to their usual hand whenever they like.' },
  { id: 'string-pull', th: 'joy', n: 'Pulled string painting', sum: 'Paint-dipped string pulled out of folded paper to make surprise shapes.',
    mins: 25, who: 'Ages 5 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 2,
    media: ['paint', 'print'],
    depth: 1,
    mat: ['Cotton string or thick wool, cut into 40 cm lengths', 'Runny poster paint in small pots', 'Paper folded in half and opened out', 'A heavy book to press with', 'Aprons, newspaper and wet wipes'],
    purpose: 'Pulling a paint-soaked string out of folded paper makes swirling, feathery shapes that nobody could plan. The reveal feels a little like magic, and the result can’t be wrong, which is a relief for anyone who worries about mistakes.',
    steps: ['Cover the table and put on aprons.', 'Dip a length of string into the paint, leaving a clean tail to hold.', 'Lay the painted string in loops on one half of the paper, with the clean tail hanging over the bottom edge.', 'Fold the other half over and press down gently with a hand or a book.', 'Keep pressing while you slowly pull the string out by its tail, wiggling it as you go.', 'Open the paper to find the shapes, printed in mirror image on both sides.', 'Add a second colour with a fresh string, then leave it to dry flat.'],
    prompts: ['Slow pull or fast pull? Try both and compare.', 'Wiggle the string and see what happens.', 'Ready? One, two, three, open!'],
    adapt: ['Young children: an adult presses the book while the child pulls.', 'Limited grip: tie the clean tail around a pencil or a paddle pop stick to make a handle.', 'Sensory-sensitive participants can wear gloves, or lay the string with a paddle pop stick.', 'Older students: try bright or metallic paint on black paper, and turn the best prints into cards.'],
    reflect: ['What happened when you pulled slowly compared with quickly?', 'Which print do you like best?', 'What would you change next time?'] },
  { id: 'bubble-prints', th: 'joy', n: 'Bubble prints', sum: 'Blowing coloured bubbles and printing their patterns onto paper.',
    mins: 30, who: 'Ages 5 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 3,
    media: ['paint', 'print'],
    depth: 1,
    mat: ['Washable paint or food colouring', 'Dishwashing liquid and water', 'Plastic cups standing in a tray', 'A straw each, with a small hole snipped near the top', 'Paper or light card'],
    purpose: 'Blowing bubbles is pure play, and the prints they leave are delicate, surprising patterns that can’t be planned or redone. Slow, steady blowing also gently lengthens the out-breath, which many people find calming.',
    steps: ['In each cup, mix about two tablespoons of paint with a big squeeze of dishwashing liquid and a little water.', 'Practise blowing out through the straw first, away from the cup.', 'Put the straw in the cup and blow gently until the bubbles rise above the rim.', 'Lay the paper lightly on the bubbles, then lift it straight off.', 'Repeat with other colours, overlapping the prints.', 'Let the prints dry flat, then keep them as they are or use them as backgrounds for drawing or collage.'],
    prompts: ['Blow out, never in.', 'Long, slow breaths make the biggest bubbles.', 'Just a light touch: kiss the bubbles with the paper.'],
    adapt: ['No-blow versions for anyone who finds blowing hard: blow bubbles onto the paper with a bubble wand, or paint bubble wrap and press paper on top.', 'Young children: an adult mixes the paint and keeps the cups in the tray.', 'Groups: give each table one colour and move from table to table to layer the prints.'],
    reflect: ['What did the bubbles do that surprised you?', 'How did the slow blowing feel?', 'Which print would you like to use as a background?'],
    care: 'Snip a small hole near the top of each straw so liquid can’t be sucked up, label straws with names and never share them. Supervise closely so nobody drinks the mixture, and keep it away from eyes.' },
  { id: 'marble-rolling', th: 'joy', n: 'Marble rolling painting', sum: 'Tilting a tray to roll paint-covered marbles across paper.',
    mins: 20, who: 'All ages · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 3,
    media: ['paint'],
    depth: 1,
    mat: ['A tray, shallow box or baking dish with sides', 'Paper cut to fit the tray', 'Marbles, or ping pong balls for bigger tracks', 'Washable paint in shallow dishes', 'A spoon to lift the marbles'],
    purpose: 'Rolling marbles through paint is simple, absorbing and hard to get wrong. The marbles go wherever the tilt takes them, which gently loosens the need for control, and it needs no drawing skill or fine grip.',
    steps: ['Lay the paper in the tray.', 'Spoon a marble into the paint and roll it around until it’s coated.', 'Lift it out with the spoon and drop it onto the paper.', 'Tilt the tray slowly one way, then another, and watch the trails appear.', 'Add more marbles in different colours, one at a time.', 'Count the marbles back into a cup before lifting the paper out to dry.'],
    prompts: ['Tilt slowly and see where it goes.', 'Can you make it zigzag? Can you make it go round and round?', 'What happens when two colours cross?'],
    adapt: ['Partners can hold a large box between them and tilt it together, which takes teamwork and brings plenty of laughs.', 'Limited grip or mobility: rest the tray on the table and nudge it with forearms, or a helper tilts while the person calls out the direction.', 'Try ping pong balls, golf balls or small toy cars for different tracks.', 'Low vision: use bold paint on contrasting paper, and listen to the marbles roll.'],
    reflect: ['Which way of tilting made your favourite marks?', 'What was it like not being fully in control?', 'What would you try next time?'],
    care: 'Marbles are a choking hazard, so keep them away from children under 3 and count them in and out. Use washable paint and aprons, and keep a towel handy for spills.' },
  { id: 'drawing-relay', th: 'joy', n: 'Team drawing relay', sum: 'Teams take turns dashing to a shared sheet to add one part each.',
    mins: 20, who: 'Groups of 6 or more · ages 6 and up',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group'],
    mess: 1,
    media: ['draw', 'move'],
    depth: 1,
    mat: ['A large sheet of paper per team, taped to a wall or an easel', 'A thick marker per team', 'A list of silly subjects, such as “a dragon at a picnic”', 'A timer'],
    purpose: 'Each person adds only one small part at a time, so nobody carries the whole drawing and there’s no time to worry about getting it right. The movement, the cheering and the silly results build team spirit fast.',
    steps: ['Split into teams of three to six, lined up a few steps back from each team’s sheet.', 'Call out a subject for everyone to draw, such as a dragon at a picnic or a teacher on holiday.', 'The first person in each line walks quickly to the sheet, adds one part in 20 seconds, then hands the marker to the next person.', 'Keep going until everyone has had two or three turns, adding details, backgrounds and patterns.', 'Now and then, call out a surprise extra for the next person to add: a hat, a pet, something flying.', 'Stop the clock and visit each team’s drawing like a gallery.', 'Give each drawing a funny title together.'],
    prompts: ['One part each, then pass the marker.', 'Help your team: what does the drawing still need?', 'We’re racing the clock, not each other.'],
    adapt: ['Seated version for wheelchair users or anyone who prefers to sit: set the sheet on a low table or easel and pass the marker along a seated line.', 'Young children: simple subjects like a house or a face, with 30 seconds a turn.', 'Older students: play a guessing version where only the first person knows the secret subject.'],
    reflect: ['What was it like adding to a drawing without planning it?', 'Which part made your team laugh the most?', 'How did your team help each other?'],
    care: 'Keep it a race against the clock, not between teams, so no drawing “loses”. Clear the floor of bags and cords, and walk rather than run indoors.' },
  { id: 'ugliest-drawing', th: 'joy', n: 'Ugliest drawing challenge', sum: 'Everyone tries their very hardest to make a terrible drawing.',
    mins: 25, who: 'Ages 6 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 1,
    media: ['draw'],
    depth: 1,
    mat: ['Paper', 'Any drawing materials, including colours nobody usually chooses', 'Sticky notes for the awards', 'Blu Tack to hang the gallery'],
    purpose: 'Setting out to make something ugly on purpose turns perfectionism upside down: there’s no way to fail, and every wonky line counts as success. It often frees up bold, loose mark making that people can carry back into their usual work.',
    steps: ['Explain the challenge: make the ugliest drawing you possibly can of a shared subject, such as a cat, a vase of flowers or a house.', 'Brainstorm ugly ideas together: clashing colours, wonky proportions, smudges, far too many eyes.', 'Draw for ten minutes, trying to break every rule you know.', 'Hang the drawings up like a gallery.', 'Invent silly awards together, such as most wonky, best clash or most confusing, and make sure every drawing gets one.', 'Look again and notice anything you secretly like, such as a bold line or a brave colour.'],
    prompts: ['Is that the worst you can do? Make it worse!', 'Try the colour you’d never normally choose.', 'There are no mistakes today, only extra ugliness.'],
    adapt: ['Younger children: call it the silliest drawing challenge instead.', 'One-to-one: the teacher makes an ugly drawing too, and the student hands out the awards.', 'Anyone who finds drawing stressful can make an ugly collage from magazine scraps.', 'Follow-up: draw the same subject “beautifully” in five minutes and compare how each felt.'],
    reflect: ['How did it feel to try to make something ugly?', 'Was it easier or harder than trying to make something good?', 'Is there anything in your drawing you’d like to use again?'],
    care: 'Make the rules clear: only the artist calls their own drawing ugly, and the awards celebrate boldness and humour, never being “bad at art”. Keep it light and kind.' },
  { id: 'comic-jam', th: 'joy', n: 'Comic jam', sum: 'A comic strip where each person draws the next panel of the story.',
    mins: 40, who: 'Ages 8 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 1,
    media: ['draw', 'words'],
    depth: 1,
    mat: ['Paper ruled into six panels, one sheet per person', 'Pencils and fine black pens', 'Coloured pencils or textas', 'Story starters on slips of paper, such as “The fridge started talking.”'],
    purpose: 'Cartoonists call this a jam: one strip, many artists, each continuing the story from the panel before. Stick figures are welcome, the plot twists in ways nobody could plan, and everyone shares the credit for the result.',
    steps: ['Each person draws the first panel of a comic on their sheet, from a story starter or their own idea.', 'Pass the sheet on. Read what has happened so far and draw the next panel to continue the story.', 'Add speech bubbles, a short caption or sound effects like “SPLAT” if you like.', 'Keep passing until each strip has five panels.', 'Return each comic to the person who started it, who draws the last panel to end the story.', 'Read the comics aloud together, sound effects and all.'],
    prompts: ['Stick figures are perfect.', 'What could go wrong next?', 'Leave the next person something fun to work with.'],
    adapt: ['One-to-one: the teacher and student pass a single strip back and forth, one panel each.', 'Young children: three big panels and no words needed.', 'Anyone who doesn’t want to draw can write the speech bubbles and captions.', 'Give everyone the same first panel and see how differently the stories end.'],
    reflect: ['Which twist in the story surprised you most?', 'How did you decide what to draw in your panel?', 'Which comic would you like to read again?'],
    care: 'Keep stories kind: no comics about real people in the class unless they’re happy to be included.' },
  { id: 'cardboard-creatures', th: 'joy', n: 'Cardboard creatures', sum: 'Odd and wonderful creatures built from clean recycling.',
    mins: 75, who: 'Ages 5 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 2,
    media: ['mixed', 'paint'],
    depth: 1,
    mat: ['Clean recycling: boxes, tubes, egg cartons, lids and bottle tops', 'Masking tape and PVA glue', 'Child-safe scissors, and adult scissors for thick card', 'Paint and brushes', 'Scraps of paper, wool and fabric for details'],
    purpose: 'Building from the recycling bin turns rubbish into characters, so the materials are free and there’s nothing precious to spoil. Working in three dimensions, solving wobbly problems with tape and giving a creature a personality are deeply satisfying at any age.',
    steps: ['Spread the recycling out and choose a few pieces that look as if they could be part of a creature.', 'Try out arrangements before sticking anything down, deciding which box is the body and which tubes are necks or legs.', 'Join the pieces with masking tape first, then strengthen the joins with PVA glue if needed.', 'Add eyes, ears, tails, wings or wheels from smaller pieces.', 'Paint the creature, or cover it in scraps of paper, wool and fabric.', 'Give it a name, decide what it eats and where it lives, and introduce it to the group.'],
    prompts: ['What could this box become?', 'If it falls over, that’s part of the design challenge.', 'What does your creature like to do on the weekend?'],
    adapt: ['Young children: adults cut holes and slots, and children tape and decorate.', 'Limited grip: tear strips of masking tape in advance and stick them along the table edge, ready to use.', 'Work in pairs or small groups to build one giant creature together.', 'Short on time: build in one class and paint in the next.'],
    reflect: ['What problem did you solve while building?', 'What is your creature called, and what is it like?', 'What would you add if you had more time?'],
    care: 'Check that the recycling is clean, with no sharp edges, food traces or allergens such as nut spreads. Supervise scissors closely and have an adult cut thick card. Keep bottle tops and small pieces away from children under 3.' },
  { id: 'dice-doodles', th: 'joy', n: 'Dice-roll doodles', sum: 'Rolling a dice to decide what your creature looks like.',
    mins: 25, who: 'Ages 6 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 1,
    media: ['draw'],
    depth: 1,
    mat: ['A dice for each table or person', 'A roll chart on a board or a sheet of paper', 'Paper and felt-tips or textas', 'Coloured pencils or crayons'],
    purpose: 'Letting the dice choose takes away the pressure of deciding what to draw, and the odd combinations it throws up are often very funny. It’s a handy warm-up for anyone who gets stuck for ideas or worries about choosing wrong.',
    steps: ['Write up a roll chart with four rows: body shape, eyes, legs or arms, and a special feature.', 'Give each row six options, for example body: 1 circle, 2 triangle, 3 cloud, 4 bean, 5 square, 6 long and wiggly.', 'For eyes and legs, the number rolled is how many to draw.', 'Roll for each row in turn and draw exactly what the dice says, with no swapping allowed.', 'Roll once more for a colour scheme or a place for the creature to live.', 'Put the creatures side by side: everyone used the same chart, yet each one is different.'],
    prompts: ['The dice is the boss today.', 'Six legs? Where will they all go?', 'How would a creature like that move?'],
    adapt: ['Limited grip: use large foam dice, or the teacher rolls for everyone.', 'For a calmer version, roll for patterns instead: lines, dots, waves, spirals, zigzags and checks.', 'Older students can design their own roll charts and swap them with another table.', 'Low vision: use dice with big dots and call out each roll.'],
    reflect: ['Which roll was the hardest to draw?', 'What did you enjoy about not choosing?', 'What would you add to the chart next time?'] },
  { id: 'funny-faces', th: 'joy', n: 'Funny face self-portraits', sum: 'Quick sketches of your silliest faces, drawn from a mirror.',
    mins: 25, who: 'Ages 6 and up · groups or one-to-one',
    ages: ['kids', 'teens', 'adults', 'older'],
    fmt: ['group', 'one'],
    mess: 1,
    media: ['draw'],
    depth: 1,
    mat: ['A small unbreakable mirror each', 'Paper folded into four boxes', 'Pencils, felt-tips or textas', 'A timer'],
    purpose: 'Pulling faces in a mirror is instantly funny, and drawing them quickly leaves no time to fuss over likeness. It eases self-portrait nerves and gets people really looking at how faces change shape.',
    steps: ['Fold the paper into four boxes.', 'Look in the mirror and pull a silly face: puffed cheeks, a huge grin, raised eyebrows or a surprised mouth.', 'Hold the face, or keep pulling it again, while you draw it in two minutes.', 'Exaggerate what you see: if your cheeks are puffed, make them enormous.', 'Pull three more faces and draw one in each box.', 'Add a caption or a thought bubble to each face.'],
    prompts: ['The sillier the face, the better.', 'What happens to your eyebrows when you’re surprised?', 'It doesn’t need to look like you. It needs to look funny.'],
    adapt: ['Anyone uncomfortable looking at themselves can draw a partner’s funny faces, or invent cartoon faces.', 'Young children: two faces with crayons, on bigger paper.', 'Low vision: feel your face as you pull each expression, then draw what your fingers found.', 'Turn the faces into a concertina book or a comic strip.'],
    reflect: ['Which face was hardest to hold?', 'What did you notice about how your face changes?', 'Which drawing makes you smile?'],
    care: 'Some people, especially teens, feel self-conscious about their faces. Make the mirror optional, take no photos without permission, and never compare drawings with real faces.' },

      /* ---------- nature and seasons ---------- */
      { id: 'leaf-rubbing-creatures', th: 'nature', n: 'Leaf rubbing creatures', sum: 'Rubbings of fallen leaves, cut out and turned into creatures.',
        mins: 35, who: 'All ages · groups or one-to-one',
        ages: ['kids', 'teens', 'adults', 'older'],
        fmt: ['group', 'one'],
        mess: 1,
        media: ['nature', 'draw', 'collage'],
        depth: 1,
        mat: ['Fallen leaves with strong veins, such as gum, fig or plane tree leaves', 'Thin paper, such as photocopy paper', 'Crayons or oil pastels with the wrappers peeled off', 'Child-safe scissors and glue sticks', 'Coloured paper or card for the background', 'Felt-tips or textas for details'],
        purpose: 'Rubbing over a leaf makes its hidden veins and edges appear as if by magic, and turning the rubbings into creatures adds a playful twist. It slows people down to notice the shapes and textures of ordinary leaves, and works indoors or out.',
        steps: ['Collect a handful of fallen leaves in different shapes and sizes, or use a bag gathered before class.', 'Place a leaf vein side up under thin paper and hold the paper still.', 'Rub firmly over it with the side of a crayon until the edges and veins appear.', 'Make several rubbings in different colours, overlapping some of them.', 'Cut out the rubbings and arrange them on coloured paper as a creature: a long leaf for a body, small ones for ears, a row for an echidna’s spines.', 'Glue them down and add eyes, legs and a setting with felt-tips.', 'Give each creature a name and a home.'],
        prompts: ['Rub with the side of the crayon, not the tip.', 'Watch the veins appear.', 'What could this leaf shape become?'],
        adapt: ['Young children: tape the leaf and paper to the table so nothing slides.', 'Limited grip: use chunky block crayons, and tape everything down so one hand is free.', 'Low vision: choose large, thick-veined leaves and dark crayons on white paper, and feel each leaf before rubbing.', 'Rainy day: use leaves collected earlier, or textured objects from around the room.', 'Older students: make a careful page of rubbings labelled with where and when each leaf was found.'],
        reflect: ['What did you notice about the leaves once they were rubbed?', 'Which leaf made the most surprising creature part?', 'Which colours worked best for rubbing?'],
        care: 'Collect only leaves that have already fallen, and never pick from living plants. Some leaves and sap can irritate the skin, so check for plant allergies first and wash hands afterwards.' },
      { id: 'sun-prints', th: 'nature', n: 'Sun prints', sum: 'Shapes of leaves and flowers printed by sunlight.',
        mins: 30, who: 'Ages 5 and up · groups or one-to-one',
        ages: ['kids', 'teens', 'adults', 'older'],
        fmt: ['group', 'one'],
        mess: 2,
        media: ['nature', 'print'],
        depth: 1,
        mat: ['Sun print paper, or cheap coloured paper that fades in the sun', 'Fallen leaves, flowers and feathers, plus keys or paper cut-outs', 'A clear acrylic sheet or a stiff plastic sleeve to hold things flat', 'Stiff card to carry each print', 'A tray of water (for sun print paper only)'],
        purpose: 'Sunlight does the printing, so the results feel like a gift from the weather rather than a test of skill. Arranging the shapes, waiting and the slow reveal encourage patience and close looking at the outlines of ordinary things.',
        steps: ['Indoors or in the shade, arrange fallen leaves, flowers and flat objects on the paper.', 'Lay the clear sheet on top to hold everything flat, and carry the print on its card.', 'Place it in full sun: a few minutes for sun print paper, or a few days on a sunny windowsill for fading paper.', 'While the sun works, wait in the shade and sketch your arrangement or watch the clouds.', 'For sun print paper, lift the objects off, rinse the paper in water for about a minute, then dry it flat.', 'For fading paper, lift the objects to find their shapes left darker against the faded paper.', 'Compare the prints and notice which edges came out sharp and which came out soft.'],
        prompts: ['Flat things with interesting edges print best.', 'What do you think will happen under the leaf?', 'Let’s guess: how long will the sun need today?'],
        adapt: ['Cloudy or rainy day: use fading paper on a sunny windowsill and check it over the following days.', 'Young children: use big, simple shapes and let the clear sheet hold them down.', 'Limited mobility: set up the print on a tray table, and a helper carries it into the sun.', 'Older students: plan a repeating pattern, or layer two prints for a more complex design.'],
        reflect: ['What surprised you when you lifted the objects off?', 'Which shapes printed most clearly?', 'What was it like waiting for the sun to do the work?'],
        care: 'Sun safety first: work in the shade where you can, and wear hats and sunscreen and keep water handy while prints are in the sun. Use fallen materials only, and follow the instructions that come with the sun print paper.' },
      { id: 'kitchen-garden-paints', th: 'nature', n: 'Kitchen and garden paints', sum: 'Making paints from spices, vegetables and soil.',
        mins: 50, who: 'Ages 6 and up · groups or one-to-one',
        ages: ['kids', 'teens', 'adults', 'older'],
        fmt: ['group', 'one'],
        mess: 3,
        media: ['paint', 'nature'],
        depth: 1,
        mat: ['Turmeric, paprika and instant coffee', 'Cooled cooking water from beetroot and red cabbage, made in advance', 'Sieved garden soil and a little PVA glue', 'Small jars or a palette, water and brushes', 'Thick paper or watercolour paper', 'Lemon juice and bicarb soda'],
        purpose: 'People have painted with earth, plants and spices for thousands of years, long before paint came in tubes. Making colours from the kitchen and garden is a curious, sensory way to slow down, and the soft, earthy results are always a little unpredictable.',
        steps: ['Cover the table, put on aprons and set out a small jar or palette well for each colour.', 'Mix half a teaspoon each of turmeric, paprika and instant coffee with a few drops of water to make yellow, orange and brown.', 'Use the cooled cooking water from beetroot for pink, and from red cabbage for purple.', 'Stir sieved soil with a little water and a few drops of PVA glue so it sticks to the paper.', 'Test each colour on a strip of paper and write its name beside it.', 'Brush some cabbage water onto the paper, then add a drop of lemon juice to turn it pink and a pinch of bicarb soda to turn it blue-green.', 'Paint a picture, a pattern or a landscape with your new colours, and let it dry flat.'],
        prompts: ['What colour do you think the beetroot will make?', 'Watch closely: what happens when the lemon goes in?', 'Notice the smell of each colour as you paint.'],
        adapt: ['Young children: the teacher mixes the colours before class, and children test and paint.', 'Sensory-sensitive participants: offer gloves, and leave out strong smells such as coffee if needed.', 'Outdoor version: paint in a shady spot with paper clipped to boards, and test colours from soil found on the spot.', 'Older students: make a colour chart and record how each colour changes over a week.'],
        reflect: ['Which natural colour surprised you most?', 'How did these paints feel different from the ones you usually use?', 'What else from the kitchen or garden would you like to test?'],
        care: 'Check food allergies before class, and make it clear that nothing is for tasting. Turmeric and beetroot stain hands and clothes, so use aprons. Anything boiled should be prepared by an adult and fully cooled before class.' },
      { id: 'land-art', th: 'nature', n: 'Land art left to change', sum: 'Arranging fallen natural things into art outdoors, then leaving it.',
        mins: 60, who: 'All ages · groups or one-to-one',
        ages: ['kids', 'teens', 'adults', 'older'],
        fmt: ['group', 'one'],
        mess: 1,
        media: ['nature'],
        depth: 1,
        mat: ['An outdoor space with fallen leaves, sticks, bark, gumnuts and seed pods', 'Bags or baskets for collecting', 'Gardening gloves (optional)', 'A camera or tablet to record the work (optional)', 'Hats, sunscreen and water'],
        purpose: 'Land art uses natural materials where they are found and is left outside to change with the wind, rain and time. The artist Andy Goldsworthy is well known for this kind of work. Making something beautiful that won’t last can ease the pressure to make it perfect and invite people to enjoy the moment.',
        steps: ['Walk the space together first and agree where the artworks can go, away from paths and garden beds.', 'Collect fallen materials only, and sort them by colour, size or shape.', 'Choose a form to try: a line, a spiral, a frame around a stone, a winding trail or a row going from light to dark.', 'Build slowly, placing one thing at a time and stepping back often to look.', 'Take a photo if you like, from above and from the side.', 'Walk around as a group to visit each work like a gallery.', 'Leave the art where it is and, if you can, come back next class to see how the wind, rain or animals have changed it.'],
        prompts: ['What colours can you find on the ground today?', 'Try sorting from lightest to darkest.', 'It doesn’t have to last. Enjoy it while it’s here.'],
        adapt: ['Wheelchair users: work on a raised surface, such as a low wall or a tray on the lap, with helpers bringing materials.', 'Rainy day: collect materials beforehand and work indoors on brown paper, then return everything outside afterwards.', 'Young children: give them a simple area to fill, such as the inside of a hula hoop.', 'Groups: build one long trail together, each person adding a section.'],
        reflect: ['What did you enjoy about using only what was there?', 'How did it feel to leave your work behind?', 'What had changed when you came back to it?'],
        care: 'Collect only fallen materials, never living plants, and don’t lift logs or rocks where snakes, spiders or other animals may shelter. Keep the art off paths so nobody trips, and away from drains and waterways. Work in the shade where possible, with hats, sunscreen and water.' },
      { id: 'sit-spot-sketch', th: 'nature', n: 'Sit spot sketchbook', sum: 'Returning to the same outdoor spot to sketch what changes.',
        mins: 25, who: 'Ages 8 and up · groups or one-to-one',
        ages: ['kids', 'teens', 'adults', 'older'],
        fmt: ['group', 'one'],
        mess: 1,
        media: ['draw', 'nature', 'words'],
        depth: 2,
        mat: ['A small sketchbook or a folded paper booklet', 'Pencils and coloured pencils', 'A clipboard', 'A cushion or mat to sit on', 'Hats, sunscreen and water'],
        purpose: 'A sit spot is one place outdoors that you return to again and again, sitting quietly to notice what is happening. Sketching it over several weeks builds patience and a sense of connection with one small patch of the world, and shows how much changes when we slow down and look.',
        steps: ['Choose a spot outside that’s safe, shady and easy to come back to, such as under a tree, beside a garden bed or near a fence.', 'Sit quietly for two minutes and just look and listen.', 'Sketch one small thing you notice: a leaf, an ant trail, a shadow or a bird.', 'Write the date, the weather and a few words about sounds, smells or temperature.', 'Add colour if you like, matching what you can see.', 'Come back to the same spot in the next few classes and start a new page each time.', 'After a few visits, look back through the pages and notice what has changed and what has stayed the same.'],
        prompts: ['What can you hear right now?', 'Look for something tiny, then something far away.', 'What’s different from last time?'],
        adapt: ['Rainy day: sit by a window that looks onto the same view and sketch from there.', 'Wheelchair users: choose a spot that can be reached on a path, and use a clipboard or a lap tray.', 'Younger children: one minute of quiet, and a picture card of things to look for.', 'Anyone who doesn’t want to draw can write words, make rubbings or take photos instead.'],
        reflect: ['What did you notice that you hadn’t seen before?', 'How did sitting still feel today?', 'What changed between your visits?'],
        care: 'Choose spots within sight of the teacher, away from ant nests, and away from areas where magpies are swooping in spring. Check for allergies to insect stings or pollen, and bring hats, sunscreen and water.' },
      { id: 'cloud-watching', th: 'nature', n: 'Cloud watching sketches', sum: 'Lying back to find shapes in the clouds, then drawing them.',
        mins: 25, who: 'All ages · groups or one-to-one',
        ages: ['kids', 'teens', 'adults', 'older'],
        fmt: ['group', 'one'],
        mess: 2,
        media: ['draw', 'nature'],
        depth: 1,
        mat: ['Blue paper or card', 'White chalk, white pastel or white crayon', 'Grey and white pencils for shading', 'A picnic rug or mats', 'Clipboards'],
        purpose: 'Finding shapes in clouds is something many of us did as children, and it’s an easy way to rest the eyes, breathe and let the imagination wander. Clouds change as you watch, which gently encourages letting go of getting things exactly right.',
        steps: ['Find a shady spot with a good view of the sky, and lie or sit back comfortably.', 'Watch the clouds for a few minutes without talking, noticing how they move and change.', 'Point out any shapes you see: animals, faces, objects or places.', 'Choose one cloud and draw it quickly in white on blue paper before it changes.', 'Add a few details to turn it into the shape you saw.', 'Draw a second cloud, or the same one again once it has changed.', 'Share your cloud pictures and see if others can spot the shapes too.'],
        prompts: ['Watch one cloud for a whole minute. What happens to it?', 'Is it fluffy, stretchy, wispy or flat?', 'If that cloud were an animal, which one would it be?'],
        adapt: ['Rainy day: watch the clouds through a window, or use photos of clouds.', 'Limited mobility: sit in a chair or wheelchair in the shade with a clear view of the sky, and use a clipboard.', 'Young children: pull cotton wool balls apart and glue them onto blue paper as cloud creatures.', 'Low vision: describe the clouds aloud together, and use thick white pastel on dark blue paper.'],
        reflect: ['What shapes did you find?', 'How did it feel to lie back and watch the sky?', 'How did your cloud change while you were drawing it?'],
        care: 'Never look directly at the sun. Choose shade, wear hats and sunscreen, and bring water. Check the ground for ants, prickles and anything sharp before anyone lies down.' },
      { id: 'twig-weaving', th: 'nature', n: 'Twig frame weaving', sum: 'Weaving wool and fallen treasures through a frame of sticks.',
        mins: 50, who: 'Ages 7 and up · groups or one-to-one',
        ages: ['kids', 'teens', 'adults', 'older'],
        fmt: ['group', 'one'],
        mess: 1,
        media: ['textile', 'nature'],
        depth: 1,
        mat: ['Four fallen sticks of about the same length, roughly 30 cm', 'Wool or string in several colours', 'Fallen leaves, feathers, grasses and gumnuts', 'Child-safe scissors', 'Masking tape'],
        purpose: 'Weaving is steady and rhythmic, and threading found natural things through a stick frame brings outdoor treasures into a small, handmade object. It gently builds focus and fine motor skills, and the finished piece can hang in a window or from a branch.',
        steps: ['Lay four sticks in a square with the ends overlapping, and tie each corner firmly by winding wool around it in a cross.', 'Tie wool to the top stick, then wind it down around the bottom stick and back up, again and again, about a finger width apart.', 'Tie off the end securely: these are the strings you’ll weave through.', 'Weave a new length of wool over one front string and under the next, all the way across.', 'On the way back, go under where you went over before, and push each row down gently.', 'Tuck leaves, feathers and grasses between the strings as you go.', 'Tie off any loose ends, add a loop at the top for hanging, and display it.'],
        prompts: ['Over, under, over, under.', 'Which treasure would you like to weave in next?', 'Push the rows down gently so they sit snugly.'],
        adapt: ['Younger children: use a paper plate with cuts around the edge as the frame, and wrap tape around the end of the wool to make a stiff needle.', 'Limited grip: use chunky wool or ribbon, and wrap tape around the end to stiffen it.', 'Rainy day: make the frame from paddle pop sticks, and use natural materials collected earlier.', 'Older students: try a three-stick triangle frame, or plan a colour pattern before starting.'],
        reflect: ['Which part of the weaving felt most relaxing?', 'Which natural treasure did you most enjoy adding?', 'Where would you like to hang your weaving?'],
        care: 'Collect fallen sticks only, and check them for sharp ends and insects before use. Supervise scissors closely.' },
      { id: 'seasons-wheel', th: 'nature', n: 'Seasons wheel', sum: 'A spinning paper wheel showing the seasons where you live.',
        mins: 45, who: 'Ages 6 and up · groups or one-to-one',
        ages: ['kids', 'teens', 'adults', 'older'],
        fmt: ['group', 'one'],
        mess: 1,
        media: ['draw', 'nature'],
        depth: 2,
        mat: ['Two paper plates per person', 'A split pin', 'Coloured pencils, felt-tips or textas', 'Child-safe scissors', 'A ruler and a pencil', 'Fallen leaves or seed pods to decorate (optional)'],
        purpose: 'Making a seasons wheel helps people notice how the year changes around them: the weather, plants, animals and favourite activities. In Australia we usually talk about four seasons, but many Aboriginal and Torres Strait Islander nations recognise more than four, read from local signs such as flowering plants and animal behaviour.',
        steps: ['Use a ruler to divide one plate into four equal sections, one each for summer, autumn, winter and spring.', 'Write the months around the edge: summer is December to February, autumn March to May, winter June to August and spring September to November.', 'Talk about what each season is like where you live: the weather, the plants and animals, what you wear and what you like doing.', 'Draw and colour each section, such as beach days in summer, falling leaves in autumn, frosty mornings in winter and jacaranda flowers in spring.', 'Cut a window the size of one section out of the second plate, stopping short of the centre.', 'Push a split pin through the centre of both plates, with the window plate on top, and open the pin out at the back.', 'Decorate the top plate and write the name of the place where you live.', 'Turn the wheel to today’s season and talk about the signs of it you can see outside.'],
        prompts: ['What does the air smell like in each season?', 'Which season is it now? What clues can you see?', 'What do you love doing in your favourite season?'],
        adapt: ['To include the seasons of the Aboriginal Country where you live, use resources from local Aboriginal organisations or invite a local Aboriginal educator, rather than guessing.', 'Young children: draw one simple thing for each season, such as sun, leaves, rain and flowers.', 'Limited grip: the teacher pushes the split pin through, and thick felt-tips are easier to hold.', 'Older students: add a ring of words for the sounds, smells and feelings of each season.'],
        reflect: ['Which season was easiest to draw, and which was hardest?', 'What did you notice about the seasons where you live?', 'What would you add to your wheel after looking outside?'],
        care: `Seasons can bring up memories of bushfires, floods or heatwaves. Keep the focus on everyday things and let everyone choose what to include. ${CHILD_SAFE}` },
      { id: 'painted-stones', th: 'nature', n: 'Painted garden stones', sum: 'Painting smooth stones with patterns and creatures for the garden.',
        mins: 40, who: 'Ages 5 and up · groups or one-to-one',
        ages: ['kids', 'teens', 'adults', 'older'],
        fmt: ['group', 'one'],
        mess: 2,
        media: ['paint', 'nature'],
        depth: 1,
        mat: ['Smooth stones from a garden or a garden centre, washed and dried', 'Acrylic or poster paint and fine brushes', 'Cotton buds and paint pens for dots and details', 'A pencil or chalk for sketching', 'Clear outdoor varnish, applied by an adult (optional)'],
        purpose: 'A stone’s shape often suggests what it could become: a ladybird, a beetle, a sleepy face or a swirl of pattern. Painting on a small, solid surface is calming and absorbing, and the finished stones can brighten a garden bed or a pot plant.',
        steps: ['Wash and dry the stones, then hold each one and turn it over in your hands.', 'Decide what its shape reminds you of: a creature, a face, a pattern or a tiny landscape.', 'Paint a base colour over the top and let it dry.', 'Sketch your design lightly in pencil or chalk.', 'Paint the details, using cotton buds or the end of a brush for dots.', 'When it’s dry, an adult can add a coat of outdoor varnish so it lasts outside.', 'Place the stones in a garden bed, a pot plant or a window box at home or at school.'],
        prompts: ['What does this stone look like to you?', 'Dots are easy: try the end of your brush.', 'Where will your stone live?'],
        adapt: ['Limited grip: rest the stone in a ball of playdough to hold it still, and use chunky brushes or paint pens.', 'Young children: dots and stripes with cotton buds, on a base colour painted by an adult if needed.', 'Low vision: choose big stones and bright paint, and feel the stone’s shape before choosing a design.', 'Groups: make a stone snake together, each person painting one section, and lay it along a garden bed.', 'Shells: paint shells bought from a craft shop rather than collecting them from a beach.'],
        reflect: ['What did your stone’s shape suggest to you?', 'Which part of painting it did you enjoy most?', 'Where would you like your stone to be?'],
        care: 'Use stones from a garden or a garden centre, never from beaches, creeks or national parks, and leave shells where they are. Don’t leave painted stones in bushland or parks, where they can harm wildlife. Stones are small and heavy, so keep them away from children under 3 and remind everyone they’re not for throwing.' },
      { id: 'pressed-flower-bookmark', th: 'nature', n: 'Pressed flower bookmark', sum: 'Pressing fallen flowers and leaves to make a bookmark.',
        mins: 30, who: 'Ages 5 and up · groups or one-to-one',
        ages: ['kids', 'teens', 'adults', 'older'],
        fmt: ['group', 'one'],
        mess: 1,
        media: ['nature', 'collage'],
        depth: 1,
        mat: ['Fallen flowers, petals and small leaves, or garden flowers picked with permission', 'Heavy books and sheets of baking paper', 'Card cut into bookmark strips', 'Clear contact or a laminator', 'A glue stick, a hole punch and ribbon'],
        purpose: 'Pressing flowers asks for patience: the petals are gathered, flattened and left for a week or two before the making begins. Arranging the delicate dried shapes is quiet, careful work, and the finished bookmark keeps a small piece of a season to use every day.',
        steps: ['Gather fallen flowers, petals and leaves, or garden flowers picked with permission. Thin, flat flowers press best.', 'Lay them flat between two sheets of baking paper inside a heavy book, with more books on top.', 'Leave them for one to two weeks until they are dry and papery.', 'Arrange the pressed pieces on a card strip, moving them around until you like the design.', 'Fix each piece with a tiny dab of glue.', 'Cover the bookmark with clear contact, or have an adult laminate it, smoothing out any bubbles.', 'Punch a hole at the top and tie on a ribbon.'],
        prompts: ['Gently: dried petals are very delicate.', 'Try moving things around before you glue.', 'Which colours have changed as they dried?'],
        adapt: ['Short on time: the teacher presses a batch of flowers a couple of weeks before class.', 'Young children: lay petals straight onto clear contact, sticky side up, then fold the other half over.', 'Limited grip: lift petals with a damp paintbrush or wide-ended tweezers.', 'Older students: make a set of cards or a small framed arrangement, labelling each flower.'],
        reflect: ['How did the flowers change as they dried?', 'What was it like handling something so delicate?', 'Who might you share a bookmark with?'],
        care: 'Use only fallen flowers or garden flowers picked with permission, and never pick native plants or wildflowers in bushland or parks. Check for pollen and plant allergies before class.' },
      { id: 'texture-rubbing-walk', th: 'nature', n: 'Texture rubbing walk', sum: 'Collecting crayon rubbings of bark, brick and other textures on a walk.',
        mins: 40, who: 'Ages 5 and up · groups or one-to-one',
        ages: ['kids', 'teens', 'adults', 'older'],
        fmt: ['group', 'one'],
        mess: 1,
        media: ['draw', 'nature'],
        depth: 1,
        mat: ['Thin paper, such as photocopy paper or tracing paper', 'Block crayons, or crayons with the wrappers peeled off', 'A clipboard for each person', 'Masking tape', 'Hats, sunscreen and water'],
        purpose: 'A rubbing walk turns an ordinary path into a treasure hunt for texture, encouraging people to touch and look closely at bark, brick, leaves and stone. Moving outdoors while collecting marks is grounding, and everyone comes back with a stack of surprising patterns to use later.',
        steps: ['Plan a short route with plenty of textures: tree bark, brick walls, paving, fences, leaves and drain covers away from the road.', 'At each stop, run your fingers over the surface and describe how it feels.', 'Hold or tape the paper against the surface and rub firmly with the side of the crayon.', 'Collect at least six rubbings, using a different colour for each one if you like.', 'Back inside, write on the back of each rubbing where it came from.', 'Play “guess the texture”: hold up a rubbing and see if others can work out what it is.', 'Keep the rubbings to use as backgrounds or in a collage another day.'],
        prompts: ['Feel it first: is it rough, smooth, bumpy or ridged?', 'Press firmly and hold the paper very still.', 'Which texture do you think will surprise us most?'],
        adapt: ['Wheelchair users: choose a smooth, step-free route with textures at seated height, such as low walls and planter boxes.', 'Rainy day: hunt for textures indoors, such as baskets, coins, shoe soles, doormats and keyboards.', 'Young children: work in pairs, with one holding the paper while the other rubs.', 'Low vision: focus on touch, choosing bold textures and dark crayons on white paper.'],
        reflect: ['Which texture surprised you most?', 'What did you notice by touching that you might have missed by looking?', 'Which rubbing would you like to use in a picture?'],
        care: 'Rub gently on tree bark so you don’t damage it, and leave moss, lichen and insects undisturbed. Keep well away from roads, stay within sight of the teacher, and bring hats, sunscreen and water.' },
      { id: 'painted-pots', th: 'nature', n: 'Painted pots and seeds', sum: 'Painting a small pot and planting seeds to watch them grow.',
        mins: 50, who: 'Ages 5 and up · groups or one-to-one',
        ages: ['kids', 'teens', 'adults', 'older'],
        fmt: ['group', 'one'],
        mess: 3,
        media: ['paint', 'nature'],
        depth: 1,
        mat: ['Small terracotta pots, or clean yoghurt tubs with holes in the bottom', 'Acrylic or outdoor paint and brushes', 'Seed-raising mix or potting mix', 'Fast-growing seeds, such as sunflowers, beans, basil or cress', 'Gardening gloves and a small spoon or trowel', 'A watering can or spray bottle'],
        purpose: 'Decorating a pot and planting a seed brings together making and caring for something living. Checking on the seeds over the following days and weeks gives a gentle routine, something to look forward to, and the quiet pleasure of watching something grow.',
        steps: ['Cover the table and paint the outside of the pot with a base colour.', 'Add patterns, creatures, flowers or your name, and leave the paint to dry while you read the seed packets together.', 'Wearing gloves, fill the pot with damp seed-raising mix to just below the rim.', 'Plant two or three seeds at the depth shown on the packet, cover them gently and press down.', 'Water gently, and add a label with the plant’s name and the date.', 'Place the pot somewhere sunny and keep the mix damp, checking every day or two.', 'Draw the seedling each week as it grows, if you like.'],
        prompts: ['What do you think will sprout first?', 'Gently does it: seeds like a soft blanket of soil.', 'How will you look after your plant this week?'],
        adapt: ['Young children: use big seeds such as beans or sunflowers, which are easy to handle and quick to sprout.', 'Limited grip: use chunky brushes, and a large spoon to fill the pot.', 'Older adults and aged care: grow herbs to smell and use, on a sunny windowsill.', 'No garden: grow cress or herbs indoors on a windowsill, and plant out later if you can.'],
        reflect: ['What did you enjoy more: painting or planting?', 'How does it feel to be looking after something living?', 'What will you look for when you check on your seeds?'],
        care: 'Potting and seed-raising mix can carry harmful bacteria, so wear gloves, keep the mix damp to reduce dust, avoid breathing it in, and wash hands well afterwards. Use plain, uncoated seeds, and keep seeds and soil away from children under 3.' },

      /* ---------- more together ---------- */
      { id: 'silent-conversation', th: 'connect', n: 'Silent drawing conversation', sum: 'Two people “talk” on one page using only lines, shapes and colours.',
        mins: 20, who: 'Ages 7 and up · groups or one-to-one',
        ages: ['kids', 'teens', 'adults', 'older'],
        fmt: ['group', 'one'],
        mess: 1,
        media: ['draw'],
        depth: 2,
        mat: ['A large sheet of paper for each pair', 'Two felt-tips, textas or crayons in different colours', 'A timer', 'Quiet music (optional)'],
        purpose: 'Without words, partners have to watch, respond and take turns, noticing each other in a new way. The page becomes a record of a back-and-forth exchange, and many people find it easier to connect through marks than through talking.',
        steps: ['Sit side by side or opposite each other with one sheet of paper between you, each holding a different colour.', 'Agree on the one rule: no talking, just drawing, until the timer goes off.', 'One person makes a mark, such as a line, a shape or a dot.', 'The other replies with a mark of their own: copying it, answering it, joining it or doing something new.', 'Keep taking turns for about five minutes, noticing how the conversation changes.', 'Try a second round where you both draw at the same time, without planning.', 'Stop, talk about what it was like, and give your page a title together.'],
        prompts: ['Reply to their mark: you could echo it, answer it or surprise them.', 'Notice the pace: fast, slow, gentle or bold?', 'There’s no right reply, just your reply.'],
        adapt: ['One-to-one: the teacher is the partner, which can be a gentle way to get to know a new student.', 'Younger children: take turns at the sound of a bell, and keep each round to two minutes.', 'If the silence feels uncomfortable, play quiet music in the background.', 'Larger groups: three or four people share a sheet of butcher’s paper and take turns around it.'],
        reflect: ['What was it like to “talk” without words?', 'When did you feel most in tune with your partner?', 'What did you notice about the way you took turns?'],
        care: 'Pair people thoughtfully, and let anyone who’s uncomfortable work with the teacher instead. If a page starts to feel like a tug of war, pause and remind everyone it’s a conversation, not a contest.' },
      { id: 'mirror-drawing', th: 'connect', n: 'Mirror me drawing', sum: 'One partner leads with marks while the other copies them at the same time.',
        mins: 15, who: 'Ages 6 and up · groups or one-to-one',
        ages: ['kids', 'teens', 'adults', 'older'],
        fmt: ['group', 'one'],
        mess: 1,
        media: ['draw', 'move'],
        depth: 1,
        mat: ['A sheet of paper for each person', 'A felt-tip or crayon each', 'Calm music (optional)'],
        purpose: 'Following a partner’s marks as they happen asks for close attention, patience and a little give and take. Swapping leaders gives everyone a turn to guide and to follow, and the matching drawings are often funny and surprisingly lovely.',
        steps: ['Warm up by mirroring each other’s hand movements in the air, slowly, like a reflection.', 'Sit facing your partner or side by side, each with your own sheet.', 'Decide who leads first. The leader draws slowly, and the follower tries to make the same marks at the same time.', 'Start with simple lines: zigzags, waves, loops and dots.', 'After two minutes, swap roles.', 'Try a round with music, letting the music set the speed and the shapes.', 'Put both sheets together and compare them, noticing what matches and what went its own way.'],
        prompts: ['Leaders, go slowly enough for your partner to keep up.', 'Watch their hand, not your page.', 'When I clap, swap leaders without stopping.'],
        adapt: ['One-to-one: the teacher leads first, then follows the student.', 'Young children: big crayons and big, slow shapes, such as circles and lines going up and down.', 'Limited grip: use chunky crayons and larger paper taped to the table.', 'Low vision: work side by side, with the leader describing each mark aloud as they draw.'],
        reflect: ['Did you prefer leading or following?', 'What helped you stay in step with your partner?', 'What surprised you when you compared your drawings?'] },
      { id: 'hoop-weaving', th: 'connect', n: 'Hula hoop group weaving', sum: 'A big shared weaving on a hula hoop, with everyone adding rounds.',
        mins: 45, who: 'Groups of 4 or more · ages 6 and up',
        ages: ['kids', 'teens', 'adults', 'older'],
        fmt: ['group'],
        mess: 1,
        media: ['textile'],
        depth: 1,
        mat: ['A hula hoop', 'Strong string or yarn for the spokes', 'Wool, ribbon and strips of old fabric in many colours', 'Child-safe scissors', 'Masking tape'],
        purpose: 'Weaving on a shared hoop lets everyone add to one big piece at the same time, so the result belongs to the whole group. The rhythm of over and under is calming, and the mix of everyone’s chosen colours and fabrics makes a bright record of the class.',
        steps: ['Before class, tie strings across the hoop so they cross in the centre like bicycle spokes, then add one extra spoke from the centre to the rim so the total is an odd number.', 'Tie the spokes together firmly where they cross in the centre.', 'Start a length of wool at the centre and weave round and round, over one spoke and under the next.', 'Take turns, or work from different sides at once, each person adding a round or a section in a colour or fabric they choose.', 'Join each new piece with a simple knot, leaving the ends to hang or tucking them in.', 'Push each round gently towards the centre so the weaving stays snug.', 'Keep going over a few classes if you like, then hang the hoop up as a group artwork.'],
        prompts: ['Round and round: over one spoke, under the next.', 'Choose a colour or a fabric that you like.', 'Who can help hold the hoop steady?'],
        adapt: ['Wheelchair users and anyone seated: rest the hoop flat on a table at a comfortable height.', 'Younger children: wrap tape around the end of the wool to make a stiff needle, and use thick wool.', 'Limited grip: use wide fabric strips, which are easier to hold and push through.', 'Smaller groups: use a smaller hoop, such as an embroidery hoop, and finer wool.'],
        reflect: ['What did you enjoy about working on one piece together?', 'Which part of the weaving did you add?', 'How does the finished hoop feel different from something made alone?'],
        care: 'Supervise scissors, and make sure there’s room for everyone to reach the hoop without crowding.' },
      { id: 'strengths-chain', th: 'connect', n: 'Strengths paper chain', sum: 'Writing strengths on paper strips and linking them into one long chain.',
        mins: 30, who: 'Ages 6 and up · groups or one-to-one',
        ages: ['kids', 'teens', 'adults', 'older'],
        fmt: ['group', 'one'],
        mess: 1,
        media: ['words', 'draw', 'collage'],
        depth: 2,
        mat: ['Strips of coloured paper, about 3 cm by 20 cm', 'Felt-tips, textas or coloured pencils', 'A glue stick or sticky tape', 'A hat or bowl with everyone’s names in it', 'A list of strength words to borrow'],
        purpose: 'Naming strengths, in ourselves and in each other, can be a confidence boost that people remember long after class. Linking every strip into one chain is a simple reminder that the group is stronger together, and drawing names from a hat means nobody is left out.',
        steps: ['Brainstorm strength words together and write them up: kind, brave, funny, patient, creative, a good listener, never gives up.', 'Everyone draws a name from the hat, swapping it back if they get their own.', 'On a strip, write a strength you’ve noticed in that person, add their name, and decorate it with small drawings or patterns.', 'On a second strip, write one of your own strengths.', 'Make the first link by looping a strip into a ring and gluing or taping the ends.', 'Thread the next strip through the ring and close it, and keep going until every strip is linked.', 'Hang the chain across the room, and read some links aloud if people are happy to.'],
        prompts: ['What have you noticed this person is good at?', 'Strengths can be quiet ones too, like being patient or noticing things.', 'How long do you think our chain will be?'],
        adapt: ['One-to-one: the student and teacher write strengths for each other, and the chain grows a link or two each lesson.', 'Young children: draw the strength instead of writing it, with an adult helping with words.', 'Anyone who finds compliments awkward can leave their own name off the strips they write.', 'Limited grip: use wider strips, with pieces of sticky tape ready along the edge of the table.'],
        reflect: ['How did it feel to read what someone noticed about you?', 'Was it easier to name someone else’s strength or your own?', 'What do you notice when you look at the whole chain?'],
        care: 'Check the strips before they’re linked so every message is kind and genuine. Some people find compliments hard to accept, so keep reading aloud optional.' },
      { id: 'our-town', th: 'connect', n: 'Our imaginary town', sum: 'Everyone makes a stand-up building, then the group builds a town.',
        mins: 60, who: 'Groups of 4 or more · ages 5 and up',
        ages: ['kids', 'teens', 'adults', 'older'],
        fmt: ['group'],
        mess: 1,
        media: ['draw', 'collage'],
        depth: 1,
        mat: ['Card or thick paper for the buildings', 'Felt-tips, textas, crayons and coloured pencils', 'Child-safe scissors', 'A long roll of butcher’s paper for the streets', 'Blu Tack or sticky tape'],
        purpose: 'Each person makes their own building, and together the buildings become a whole town, so everyone’s ideas count and everyone belongs in the finished piece. Planning the streets, parks and shared places sparks conversation, cooperation and lots of imaginative stories.',
        steps: ['Talk together about what a town needs: homes, shops, a library, a park, a pool, perhaps a dragon stable.', 'Everyone chooses one building to make, real or imaginary, so the town has a mix.', 'Draw the building on card, leaving a strip along the bottom to fold back as a stand.', 'Add windows, doors, signs, plants and people, and colour it in.', 'Cut it out, fold back the stand and check that it stands up.', 'Roll out the butcher’s paper and draw roads, paths, a river and parks together, deciding where each building should go.', 'Stand the buildings in place with a little Blu Tack, then add cars, trees, animals and street names.', 'Give the town a name and take a tour, with each person telling everyone who lives or works in their building.'],
        prompts: ['What would make our town a good place to live?', 'Who might live or work in your building?', 'What does our town still need?'],
        adapt: ['Wheelchair users and anyone seated: build the town on tables pushed together rather than on the floor.', 'Younger children: an adult cuts out the buildings, and children draw and decorate them.', 'Older students: design a town of the future or a town under the sea, with a map key.', 'Anyone who doesn’t want to draw can make their building from magazine collage or a small box.'],
        reflect: ['Which part of the town are you proudest of?', 'How did the group decide where things went?', 'What would you like to add to the town next time?'],
        care: 'When placing the buildings, make sure every building gets a good spot and every voice is heard. Supervise scissors.' },
      { id: 'shared-palette', th: 'connect', n: 'Shared palette challenge', sum: 'Everyone paints with the same three colours, then compares results.',
        mins: 40, who: 'Ages 7 and up · groups or one-to-one',
        ages: ['kids', 'teens', 'adults', 'older'],
        fmt: ['group', 'one'],
        mess: 2,
        media: ['paint'],
        depth: 1,
        mat: ['Three paint colours chosen at random, plus white', 'Palettes or paper plates', 'Brushes and water pots', 'Paper or card', 'A shared subject, such as a bowl of fruit'],
        purpose: 'Working from the same small palette means everyone faces the same puzzle, so the talk shifts from whose painting is best to how many different answers there can be. Mixing new colours from just a few is absorbing, and comparing the results celebrates each person’s way of seeing.',
        steps: ['Draw three colour cards from a hat, or let the group vote, to choose the palette for the day.', 'Set out the same three colours and white for everyone.', 'Make a quick mixing chart first: see how many new colours you can make from the three.', 'Paint the same subject, such as a bowl of fruit, a place everyone knows or an animal, using only the shared palette.', 'Lay all the paintings side by side and notice how differently each person used the same colours.', 'Each person points out one colour they mixed that they’re pleased with.'],
        prompts: ['How many colours can you make from just these?', 'What happens if you add a tiny bit of white?', 'Look how many different paintings came from the same pots.'],
        adapt: ['One-to-one: the teacher and student paint side by side with the same palette, then compare.', 'Younger children: two colours plus white is plenty.', 'Low vision: choose strongly contrasting colours and paint on larger paper.', 'Older students: take the palette from a famous painting, or from the colours outside the window.'],
        reflect: ['Which new colour did you enjoy mixing most?', 'What did you notice when we put all the paintings together?', 'How did having fewer colours change the way you painted?'],
        care: 'Keep the comparing curious, not competitive: the point is how many different answers there are.' },
      { id: 'story-map', th: 'connect', n: 'Class story map', sum: 'The group invents a story together and draws it as a big map.',
        mins: 45, who: 'Groups of 3 or more · ages 6 and up',
        ages: ['kids', 'teens', 'adults', 'older'],
        fmt: ['group'],
        mess: 1,
        media: ['draw', 'words'],
        depth: 1,
        mat: ['A long roll of butcher’s paper', 'Felt-tips, textas and crayons', 'Sticky notes', 'A story starter, such as “a lost key” or “a dragon who can’t fly”'],
        purpose: 'A story map turns the group’s ideas into one big picture, with each person adding places, characters and twists. It encourages listening and building on each other’s ideas, and the finished map holds the whole story at a glance.',
        steps: ['Start with a story starter and agree on a main character together.', 'Draw a winding path across the paper from a starting point to an unknown ending.', 'Take turns adding a place along the path, such as a forest, a cave, a market or a stormy sea, and say what happens there.', 'Build on what has already happened, with one rule: say “yes, and…” rather than “no”.', 'Add characters, dangers, helpers and treasures to the map as the story grows.', 'Decide the ending together and draw it at the end of the path.', 'Retell the whole story by walking a finger or a small toy along the map.'],
        prompts: ['What happens to our hero here?', 'Yes, and… what happens next?', 'Who might help them on the way?'],
        adapt: ['Wheelchair users and anyone seated: lay the map across tables pushed together rather than on the floor.', 'Younger children: the teacher writes the story while children draw the places.', 'Anyone who doesn’t want to draw can tell their part aloud or write the words on sticky notes.', 'Older students: give the map a key and a compass, and write the story up as a short book.'],
        reflect: ['Which part of the story did you add?', 'What was it like building on other people’s ideas?', 'Which place on the map would you most like to visit?'],
        care: 'Make sure everyone gets a turn, and keep the story kind, with no characters based on people in the room unless they’re happy to be included.' },

      /* ---------- more mindful making ---------- */
      { id: 'one-line-drawing', th: 'mind', n: 'One continuous line', sum: 'Drawing an object without lifting the pen from the paper.',
        mins: 20, who: 'Ages 8 and up · groups or one-to-one',
        ages: ['kids', 'teens', 'adults', 'older'],
        fmt: ['group', 'one'],
        mess: 1,
        media: ['draw'],
        depth: 1,
        mat: ['Paper, A4 or larger', 'A fine black pen or felt-tip', 'Simple objects, such as a pot plant, a mug or a shoe', 'A timer'],
        purpose: 'Drawing in one unbroken line keeps attention on the edge you’re following, one moment at a time, a bit like a slow walk. Because the line can’t be lifted or rubbed out, wobbles and extra loops simply become part of the drawing, which gently loosens perfectionism.',
        steps: ['Choose an object and place it where you can see it clearly.', 'Take a slow breath, put the pen on the paper, and decide not to lift it until you finish.', 'Let your eyes travel slowly along the edges of the object while the pen follows at the same speed.', 'To move to another part, let the line travel across the drawing rather than lifting the pen.', 'Keep going for about five minutes, including inner shapes, folds and shadows.', 'Lift the pen only when you feel finished, then look at the drawing as a whole.', 'Try again with a different object, or with your other hand resting on the table as the subject.'],
        prompts: ['Imagine your pen is an ant walking slowly along the edge.', 'If the line goes somewhere unexpected, just keep going.', 'Notice how quiet the room has become.'],
        adapt: ['Younger children: draw a simple object, such as a cup or a leaf, with a crayon.', 'Limited grip: use a thick marker on larger paper taped to the table.', 'Low vision: use a bold pen on white paper, and feel the object’s edges before drawing.', 'For a challenge, draw a person, a whole room or the view out of a window in one line.'],
        reflect: ['What happened to your thoughts while you followed the line?', 'What did you notice about the object that you hadn’t seen before?', 'How did it feel not being able to lift the pen?'] },
      { id: 'tea-bag-painting', th: 'mind', n: 'Tea-bag painting', sum: 'Painting with used tea bags and coffee for soft, warm browns.',
        mins: 30, who: 'Ages 7 and up · groups or one-to-one',
        ages: ['kids', 'teens', 'adults', 'older'],
        fmt: ['group', 'one'],
        mess: 2,
        media: ['paint'],
        depth: 1,
        mat: ['Used tea bags, cooled, and a jar of strong cold tea or instant coffee', 'Thick paper or watercolour paper', 'A clothes peg for each tea bag', 'Brushes and a jar of water', 'A fine black pen for drawing into the dry painting', 'Paper towels and a tray'],
        purpose: 'Tea and coffee make gentle, warm washes that dry into soft, uneven shades, so there’s no way to get the colour wrong. The smell, the slow spread of the stain and the simple, homely materials make this a quiet way to settle into making.',
        steps: ['Make the tea or coffee in advance and let it cool completely.', 'Clip a clothes peg to the top of each used tea bag to make a handle.', 'Dab and drag a tea bag across the paper to make soft shapes and blotches.', 'Brush on cold tea or coffee for lighter washes, and add more layers once dry for darker shades.', 'Drop a little clean water onto a wet patch and watch it bloom outwards.', 'Leave the painting to dry, noticing how the colours change as it dries.', 'Once dry, draw into the shapes with a fine pen to find hills, creatures or a treasure map.'],
        prompts: ['Breathe in: what can you smell?', 'Let the tea bag make the shapes for you.', 'Look at the edges where the tea dried darker.'],
        adapt: ['Younger children: put cold tea in a spray bottle and spray it over paper shapes laid on the page.', 'Sensory-sensitive participants: offer gloves, or a brush instead of handling the tea bags.', 'Older students: stain a whole sheet first, then use it for drawing, lettering or an old-looking map.', 'Groups: try different teas, such as black, green, rooibos or hibiscus, and compare the colours.'],
        reflect: ['What did you notice about the smells and the colours?', 'How did the stains change as they dried?', 'What did you find when you drew into the shapes?'],
        care: 'Make sure the tea and coffee are completely cool before anyone handles them, and make it clear that nothing is for drinking. Tea stains, so use aprons and cover the table.' },
      { id: 'ten-minute-object', th: 'mind', n: 'Ten-minute object drawing', sum: 'One everyday object, drawn in stages over ten timed minutes.',
        mins: 20, who: 'Ages 9 and up · groups or one-to-one',
        ages: ['kids', 'teens', 'adults', 'older'],
        fmt: ['group', 'one'],
        mess: 1,
        media: ['draw'],
        depth: 1,
        mat: ['An everyday object each, such as a mug, a shoe, a set of keys or a pot plant', 'A pencil and an eraser', 'Drawing paper', 'A timer or a chime'],
        purpose: 'Most of us draw the idea of a thing rather than the thing itself. Giving one ordinary object a full ten minutes, with a new focus every two minutes, slows the hand and the mind, and shows how much there is to see in something we use every day.',
        steps: ['Place the object in front of you and set a timer to chime every two minutes.', 'Minutes 1–2: draw the outside shape lightly, looking at the object more than the paper.', 'Minutes 3–4: look at the spaces around and through the object, and adjust the shape.', 'Minutes 5–6: add the shadows and the brightest highlights.', 'Minutes 7–8: add textures, such as shine, scratches, grain or fabric.', 'Minutes 9–10: choose one small detail and draw it very carefully.', 'When the last chime sounds, put the pencil down, even if the drawing feels unfinished.', 'Take a breath, look at the object and the drawing together, and notice what you saw.'],
        prompts: ['Look longer than you draw.', 'Unfinished is fine. We’re practising looking.', 'What do you see now that you didn’t see at the start?'],
        adapt: ['Younger students: five minutes, with a chime every minute, and a crayon.', 'Low vision: use a large, high-contrast object under a lamp, and allow touching it.', 'If timers feel stressful, skip the chime and give a gentle spoken reminder to move on.', 'Older students: draw the same object each week and compare the drawings.'],
        reflect: ['Which stage made you look hardest?', 'What surprised you about the object?', 'How did the time feel: quick or slow?'] },
      { id: 'mindful-paper-boat', th: 'mind', n: 'Mindful paper folding', sum: 'Folding a paper boat slowly, one crease at a time.',
        mins: 25, who: 'Ages 7 and up · groups or one-to-one',
        ages: ['kids', 'teens', 'adults', 'older'],
        fmt: ['group', 'one'],
        mess: 1,
        media: ['mixed'],
        depth: 1,
        mat: ['A4 paper, plain or patterned', 'A clear, flat table', 'Felt-tips for decorating (optional)', 'A tub of water for testing the boats (optional)'],
        purpose: 'Origami, the Japanese art of paper folding, asks for slow, careful attention to each crease. Folding a simple paper boat with the breath turns a familiar childhood craft into a quiet, focused practice, and there’s a satisfying moment when the flat paper suddenly becomes a boat.',
        steps: ['Sit comfortably, take three slow breaths, and run your hands over the paper.', 'Fold the sheet in half from top to bottom, press the crease with a fingernail, and keep the fold at the top.', 'Fold it in half from side to side to mark the centre, then open that fold again.', 'Fold the top corners down to meet the centre line, making a roof shape.', 'Fold the bottom strip on the front up over the roof, then turn it over and fold the back strip up too, to make a hat.', 'Open the hat from the bottom, bring the two ends together and flatten it into a diamond.', 'Fold the bottom point of the front layer up to the top, turn it over and do the same on the back, then open and flatten it into a diamond again.', 'Hold the two loose top flaps, one in each hand, and gently pull them apart. The boat rises up in the middle.', 'Shape the boat, decorate it if you like, and float it in a tub of water.'],
        prompts: ['One fold at a time. There’s no rush.', 'Press each crease slowly and listen to the sound it makes.', 'Watch closely: the boat is about to appear.'],
        adapt: ['Younger children: fold alongside the teacher step by step, using larger paper.', 'Limited grip: use thinner paper, and press the creases with a paddle pop stick or with help from a partner.', 'Older adults: if the later folds feel fiddly, stop at the hat, which is a lovely shape in itself.', 'For a challenge, older students can fold a traditional origami crane from a square of paper.'],
        reflect: ['Which fold needed the most concentration?', 'What did you notice about your breathing while folding?', 'How did it feel when the boat appeared?'] },
      { id: 'enso-circles', th: 'mind', n: 'Zen ink circles', sum: 'Painting single brush circles, each in one breath and one stroke.',
        mins: 25, who: 'Ages 10 and up · groups or one-to-one',
        ages: ['kids', 'teens', 'adults', 'older'],
        fmt: ['group', 'one'],
        mess: 3,
        media: ['paint'],
        depth: 2,
        mat: ['Washable black ink, or black paint watered down', 'A large, soft round brush', 'Plenty of cheap paper, such as newsprint or butcher’s paper', 'A saucer for the ink and a jar of water', 'Newspaper to protect the table'],
        purpose: 'The ensō is a circle painted in one flowing brushstroke, a practice that comes from Japanese Zen calligraphy. Each circle is made in a single breath and left exactly as it is, so the aim is presence rather than perfection, and repeating it many times can be very calming.',
        steps: ['Sit or stand comfortably with plenty of paper ready, and load the brush so it’s full but not dripping.', 'Breathe in, then as you breathe out, paint a circle in one movement without stopping.', 'Leave it exactly as it is: open or closed, thick or thin, wobbly or smooth.', 'Put that sheet aside and paint another circle on a fresh sheet.', 'Paint at least ten circles, noticing your breath, your arm and the brush.', 'Lay them all out and notice how they differ, without picking a best one.'],
        prompts: ['One breath, one circle.', 'Let each circle be exactly as it comes.', 'Notice the brush, the ink and your arm moving together.'],
        adapt: ['Water version: paint circles with plain water on a dark paver or a chalkboard, and watch them fade away.', 'Limited grip: use a thick brush with a foam grip, or a sponge on a stick.', 'Younger students: big circles with chunky brushes and poster paint.', 'Anyone who finds ink too messy can use a brush pen or a thick black felt-tip.'],
        reflect: ['How did your circles change as you went on?', 'What was it like to leave each circle as it was?', 'What did you notice about your breathing?'],
        care: 'Introduce the ensō respectfully as part of a Zen tradition, and keep the focus on the practice rather than on a perfect circle. Use washable ink and cover clothes, as ink stains.' },
      { id: 'one-colour-hunt', th: 'mind', n: 'One-colour hunt', sum: 'Hunting for every shade of one colour around the room.',
        mins: 15, who: 'All ages · groups or one-to-one',
        ages: ['kids', 'teens', 'adults', 'older'],
        fmt: ['group', 'one'],
        mess: 1,
        media: ['draw', 'move'],
        depth: 1,
        mat: ['A sheet of paper folded into six boxes', 'Coloured pencils, crayons or felt-tips', 'Colour cards or paint swatches (optional)', 'A clipboard'],
        purpose: 'Choosing just one colour and searching for it everywhere brings attention to the present and to things we usually overlook. Moving slowly around the room while counting and sketching is calming, and people are often surprised by how many shades of one colour there are.',
        steps: ['Choose one colour, or draw a colour card from a bag.', 'Walk slowly around the room in silence, looking for everything in that colour, high and low.', 'Keep a tally on your page of how many things you find.', 'Sketch five of them in quick thumbnails, one in each box, and colour them as closely as you can.', 'Notice the different shades: some will be warmer, cooler, lighter or darker.', 'Come back together, share your counts and put the pages side by side.'],
        prompts: ['Look up, look down, look under things.', 'Is this green more yellowy or more bluey than that one?', 'Move slowly, like a detective.'],
        adapt: ['Wheelchair users or anyone seated: hunt from one spot, turning slowly to look all around, or hunt through a tray of objects.', 'Young children: hunt for a bright, easy colour such as red, and tick a box for each find.', 'Low vision: choose a strong colour and use a magnifier, or hunt by touch for one texture instead.', 'Outdoors: take the hunt into a garden or a playground.'],
        reflect: ['How many did you find?', 'Which shade surprised you?', 'How did it feel to look so closely at the room?'] }
    );
